        listId: wishlist.id,
        // SDK param widening — `useCustomerId` returns `string | null`; this branch is only
        // reachable once a wishlist has loaded, which requires a customer.
        customerId: customerId as string,
      },
      body: {
        quantity,
        productId: variant?.productId || product?.id,
        public: false,
        priority: 1,
        type: 'product',
      },
    },
    { onError: () => showError() },
  );
};

// SFCC-434, AC4 — re-derives the list item at call time (the same lookup handleAddToWishlist
// already does for the add path above) rather than requiring ProductView to hand back an item
// id it was never given.
const handleRemoveFromWishlist = (product: SfccProduct, variant: SfccVariant) => {
  const currentProductId = variant?.productId || product?.productId || product?.id;
  const item = wishlist?.customerProductListItems?.find(
    (i: { productId?: string; id: string }) => i.productId === currentProductId,
  );
