/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff beyond: the TypeScript annotations below, an explicit
 * `undefined` default value passed to `createContext` (React's TS types require this parameter;
 * the base file's argument-less `createContext()` call is only legal in untyped JS, where an
 * omitted argument is implicitly `undefined` at runtime too — same value, just spelled out so it
 * type-checks), and a temporary `[overrides]` console.log marker (verified live, then removed).
 * Styling/behaviour changes are a later commit (2.2), not this one.
 *
 * `SfccVariant` is kept as `any` with a named alias rather than a structural type invented from
 * usage — this package ships no TypeScript types for this shape, matching the same documented gap
 * at overrides/app/components/product-view/index.tsx:136-151.
 */
import React, { createContext, useContext } from 'react';

/**
 * This component and associated context/hook provide a convenient wrapper
 * around a group of components used for rendering product variant details.
 */

type SfccVariant = any;

const ItemVariantContext = createContext<SfccVariant>(undefined);

export const useItemVariant = (): SfccVariant => {
  return useContext(ItemVariantContext);
};

type ItemVariantProviderProps = {
  // CodeRabbit (SFCC-11 cumulative review): was `variant?:` - an omitted variant flows straight
  // into context as `undefined`, and consumers (ItemPrice/ItemName, via useItemVariant) destructure
  // properties off it unguarded, which would throw on render. Required instead: the only real
  // caller (product-item/index.tsx) always passes `product`, itself a required prop - a pure
  // type-level tightening, no runtime behaviour change for any existing caller.
  variant: SfccVariant;
  children?: React.ReactNode;
};

/**
 * The Provider component for rendering product item and variant detail.
 */
const ItemVariantProvider = ({ variant, children }: ItemVariantProviderProps) => {
  return <ItemVariantContext.Provider value={variant}>{children}</ItemVariantContext.Provider>;
};

export default ItemVariantProvider;

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import {useEffect, useState} from 'react'
import {useVariant} from '@salesforce/retail-react-app/app/hooks/use-variant'
import {useIntl} from 'react-intl'
import {useVariationParams} from '@salesforce/retail-react-app/app/hooks/use-variation-params'
import {useVariationAttributes} from '@salesforce/retail-react-app/app/hooks/use-variation-attributes'
import {useSelectedStore} from '@salesforce/retail-react-app/app/hooks/use-selected-store'

const OUT_OF_STOCK = 'OUT_OF_STOCK'
const UNFULFILLABLE = 'UNFULFILLABLE'

const getInventoryById = (product, inventoryId) => {
    if (!inventoryId || !product?.inventories) {
        return null
    }
    return product.inventories.find((inv) => inv.id === inventoryId)
}

// TODO: This needs to be refactored.
// If compatibility with API version < v8.1 is needed, keep pickupInStore as false
export const useDerivedProduct = (
    product,
    isProductPartOfSet = false,
    isProductPartOfBundle = false,
    pickupInStore = false,
    controlledVariationValues = null,
    onVariationChange = null
) => {
    const showLoading = !product
    const isProductABundle = product?.type?.bundle
    const stockLevel = product?.inventory?.stockLevel || 0
    const stepQuantity = product?.stepQuantity || 1
    const minOrderQuantity = stockLevel > 0 ? product?.minOrderQuantity || 1 : 0
    const initialQuantity = product?.quantity || product?.minOrderQuantity || 1

    // used for product bundles when there are multiple products
    const lowestStockLevelProductName = product?.inventory?.lowestStockLevelProductName
    const intl = useIntl()
    const variant = useVariant(
        product,
        isProductPartOfSet,
        isProductPartOfBundle,
        controlledVariationValues
    )
    const isStandardProduct = product?.type?.item
    const variationParams = useVariationParams(
        product,
        isProductPartOfSet,
        isProductPartOfBundle,
        controlledVariationValues
    )
    const variationAttributes = useVariationAttributes(
        product,
        isProductPartOfSet,
        isProductPartOfBundle,
        controlledVariationValues,
        onVariationChange
    )
    const [quantity, setQuantity] = useState(initialQuantity)
    const {selectedStore} = useSelectedStore()

    // A product is considered out of stock if the stock level is 0 or if we have all our
    // variation attributes selected, but don't have a variant. We do this because the API
    // will sometimes return all the variants even if they are out of stock, but for other
    // products it won't.
    const isOutOfStock =
        !stockLevel ||
        (!isProductABundle &&
            !variant &&
            !isStandardProduct &&
            Object.keys(variationParams).length === variationAttributes.length) ||
        (!isProductABundle && variant && !variant.orderable)
    const unfulfillable = stockLevel < quantity

    // Product details for selected store
    const selectedStoreInventory = getInventoryById(product, selectedStore?.inventoryId)
    const selectedStoreStockLevel = selectedStoreInventory?.stockLevel || 0
    const selectedStoreLowestStockLevelProductName =
        selectedStoreInventory?.lowestStockLevelProductName
    // selectedStoreStockLevel and selectedStoreInventory are already variant specific,
    // so we don't need to check for variation attributes
    const isSelectedStoreOutOfStock = !selectedStoreStockLevel || !selectedStoreInventory?.orderable
    const selectedStoreUnfulfillable = selectedStoreStockLevel < quantity

    // Use appropriate inventory based on pickup/delivery selection
    const currentStockLevel = pickupInStore ? selectedStoreStockLevel : stockLevel
    const currentLowestStockLevelProductName = pickupInStore
        ? selectedStoreLowestStockLevelProductName
        : lowestStockLevelProductName
    const currentIsOutOfStock = pickupInStore ? isSelectedStoreOutOfStock : isOutOfStock
    const currentUnfulfillable = pickupInStore ? selectedStoreUnfulfillable : unfulfillable

    const inventoryMessages = {
        [OUT_OF_STOCK]: intl.formatMessage({
            defaultMessage: 'Out of stock',
            id: 'use_product.message.out_of_stock'
        }),
        [UNFULFILLABLE]: currentLowestStockLevelProductName
            ? intl.formatMessage(
                  {
                      defaultMessage: 'Only {stockLevel} left for {productName}!',
                      id: 'use_product.message.inventory_remaining_for_product'
                  },
                  {stockLevel: currentStockLevel, productName: currentLowestStockLevelProductName}
              )
            : intl.formatMessage(
                  {
                      defaultMessage: 'Only {stockLevel} left!',
                      id: 'use_product.message.inventory_remaining'
                  },
                  {stockLevel: currentStockLevel}
              )
    }

    // showInventoryMessage controls if add to cart button is disabled
    const showInventoryMessage =
        (variant || isProductABundle || isStandardProduct) &&
        (currentIsOutOfStock || currentUnfulfillable)
    const inventoryMessage =
        (currentIsOutOfStock && inventoryMessages[OUT_OF_STOCK]) ||
        (currentUnfulfillable && inventoryMessages[UNFULFILLABLE])

    // If the `initialQuantity` changes, update the state. This typically happens
    // when either the master product changes, or the inventory of the product changes
    // from out-of-stock to in-stock or vice versa.
    useEffect(() => {
        setQuantity(initialQuantity)
    }, [initialQuantity])

    // Lump the out of stock/unfulfillable checks together for easier consumption
    return {
        showLoading,
        showInventoryMessage,
        inventoryMessage,
        variationAttributes,
        quantity,
        minOrderQuantity,
        stepQuantity,
        variationParams,
        setQuantity,
        variant,
        stockLevel,
        isOutOfStock,
        unfulfillable,
        isSelectedStoreOutOfStock: isSelectedStoreOutOfStock || selectedStoreUnfulfillable,
        selectedStore
    }
}

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-image.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff at that step beyond the TypeScript annotations and a
 * temporary `[overrides]` console.log marker (verified live, then removed).
 *
 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec. The outer Box's own literal
 * `width="84px" backgroundColor="gray.100"` defaults are gone, replaced by item-variant.css.ts's
 * `image` part via `__css` — kept as `__css`, not `sx`, specifically so a caller-supplied
 * `width`/`mr` (e.g. order-summary/index.jsx's base, not-yet-overridden
 * `<CartItemVariantImage width="80px" mr={2} />`) still wins; see that recipe's own docblock for
 * why. `{...props}` stays spread last, same defaults-then-spread order as before, still what
 * lets that caller-supplied width win. `ratio`'s default changed from `1` to the Figma-confirmed
 * 288/432 cart-item image ratio; the inner <Image> now also carries the `img` part's responsive
 * objectFit + mix-blend-multiply. Badge styling (Sale/Unavailable) is untouched — no Figma value
 * was given for it at this step.
 */
import React from 'react';
import {
  AspectRatio,
  Box,
  Badge,
  Image,
  useMultiStyleConfig,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { useItemVariant } from '.';
import { FormattedMessage } from 'react-intl';
import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';
// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
// redeclared per file.
import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

type ItemImageProps = {
  imageProps?: Record<string, any>;
  ratio?: number;
} & Record<string, any>;

// Figma "Image" spec, product-item card (SFCC-270): aspect ratio 288/432, which reduces to 2/3
// exactly. Matches the design record's own 132x198 desktop pair exactly (132 * 432/288 = 198);
// against the 67x100 mobile pair it lands at 100.5 — half a pixel over the stated 100, the same
// class of Figma-rounding gap zimmDrawer.css.ts's WIDTH_XLARGE note already documents for a
// different value, not something introduced here.
const CART_ITEM_IMAGE_RATIO = 288 / 432;

/**
 * In the context of a cart product item variant, this component renders the item's
 * main image.
 *
 * @todo = This component will render a `SALE` badge when the qualifier is available
 * on the custom property `c_isSale`. This will need to be expanded upon to handle
 * different badge/qualifiers and property names.
 */
const ItemImage = ({ imageProps, ratio = CART_ITEM_IMAGE_RATIO, ...props }: ItemImageProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});

  // We find the 'small' images in the variant's image groups based on variationValues and pick the first one
  const image = findImageGroupBy(variant?.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: variant?.variationValues,
  })?.images?.[0];

  return (
    <Box __css={styles.image} {...props}>
      <AspectRatio ratio={ratio}>
        <Box position="relative">
          {variant.c_isSale && (
            <Badge
              position="absolute"
              top={0}
              left={0}
              marginLeft={2}
              marginTop={2}
              fontSize="10px"
              variant="solid"
              colorScheme="blue"
            >
              <FormattedMessage
                defaultMessage="Sale"
                id="item_image.label.sale"
                description="A sale badge placed on top of a product image"
              />
            </Badge>
          )}
          {variant.isProductUnavailable && (
            <Badge
              position="absolute"
              top={0}
              left={0}
              marginLeft={2}
              marginTop={2}
              fontSize="10px"
              variant="solid"
              colorScheme="red"
            >
              <FormattedMessage
                defaultMessage="Unavailable"
                id="item_image.label.unavailable"
                description="A unavailable badge placed on top of a product image"
              />
            </Badge>
          )}

          {image && (
            <Image
              alt={image.alt}
              src={`${image.disBaseLink || image.link}`}
              ignoreFallback={true}
              __css={styles.img}
              {...imageProps}
            />
          )}
        </Box>
      </AspectRatio>
    </Box>
  );
};

export default ItemImage;

