import React, { ErrorInfo } from 'react';

type ErrorFallbackState = { hasError: boolean };

/** Error boundary for ZimmAuthDrawerContent — class component required by React's error boundary API. */
export class ErrorFallback extends React.Component<React.PropsWithChildren, ErrorFallbackState> {
  constructor(props: React.PropsWithChildren) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(): ErrorFallbackState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    // console.error is permitted inside error boundaries per conventions.md
    console.error('[ZimmAuthDrawerContent] render error', error, info.componentStack);
  }

  render(): React.ReactNode {
    if (this.state.hasError) {
      // Intentionally blank — if any auth sub-component crashes (email/OTP input, social
      // buttons, create-account panel) the drawer shows empty rather than a broken UI.
      // A Zimmermann-designed error state can replace this null once confirmed.
      return null;
    }
    return this.props.children;
  }
}

