538	    test('increment: calls onItemQuantityChange with quantity + 1, and commits it locally when the mutation resolves true', async () => {
539	      mockUseDerivedProduct.mockReturnValue({
540	        stepQuantity: 1,
541	        showInventoryMessage: false,
542	        inventoryMessage: '',
543	        quantity: 2,
544	        setQuantity: mockSetQuantity,
545	      });
546	      const onItemQuantityChange = vi.fn().mockResolvedValue(true);
547	      renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} onItemQuantityChange={onItemQuantityChange} />);
548	
549	      fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
550	
551	      expect(onItemQuantityChange).toHaveBeenCalledWith(3);
552	      await waitFor(() => expect(mockSetQuantity).toHaveBeenCalledWith(3));
553	    });
554	
555	    test('increment: calls onItemQuantityChange, but does NOT commit locally when the mutation resolves false', async () => {
556	      mockUseDerivedProduct.mockReturnValue({
557	        stepQuantity: 1,
558	        showInventoryMessage: false,
559	        inventoryMessage: '',
560	        quantity: 2,
561	        setQuantity: mockSetQuantity,
562	      });
563	      const onItemQuantityChange = vi.fn().mockResolvedValue(false);
564	      renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} onItemQuantityChange={onItemQuantityChange} />);
565	
566	      fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
567	
568	      expect(onItemQuantityChange).toHaveBeenCalledWith(3);
569	      // Flush the mutation's own microtask queue (the Promise.resolve(...).then(...) inside
570	      // handleStepperQuantityChange) before asserting the negative — otherwise this would pass
571	      // trivially before the .then callback has even had a chance to run.
572	      await new Promise((resolve) => setTimeout(resolve, 0));
573	      expect(mockSetQuantity).not.toHaveBeenCalled();
574	    });
575	
576	    test('decrement: calls onItemQuantityChange with quantity - 1, and commits it locally when the mutation resolves true', async () => {
577	      mockUseDerivedProduct.mockReturnValue({
578	        stepQuantity: 1,
579	        showInventoryMessage: false,
580	        inventoryMessage: '',
581	        quantity: 2,
582	        setQuantity: mockSetQuantity,
583	      });
584	      const onItemQuantityChange = vi.fn().mockResolvedValue(true);
585	      renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} onItemQuantityChange={onItemQuantityChange} />);
586	
