607	      await new Promise((resolve) => setTimeout(resolve, 0));
608	      expect(mockSetQuantity).not.toHaveBeenCalled();
609	    });
610	
611	    // Same widened-type fix already proven for product-quantity-picker.tsx's own
612	    // handleQuantityChange (CodeRabbit, SFCC-11 cumulative review): a caller-supplied SYNCHRONOUS
613	    // (non-Promise) onItemQuantityChange must not throw via handleStepperQuantityChange's own
614	    // Promise.resolve(...) normalisation either.
615	    test('a synchronous (non-Promise) onItemQuantityChange also works via increment', async () => {
616	      mockUseDerivedProduct.mockReturnValue({
617	        stepQuantity: 1,
618	        showInventoryMessage: false,
619	        inventoryMessage: '',
620	        quantity: 2,
621	        setQuantity: mockSetQuantity,
622	      });
623	      const onItemQuantityChange = vi.fn(() => true);
624	      renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} onItemQuantityChange={onItemQuantityChange} />);
625	
