347	    // render via its same-value setState optimisation — no second render ever happens for that
348	    // mutation to be caught by). This test instead forces a SECOND real render with the SAME
349	    // basket via an explicit rerender() (an effect-irrelevant prop change — onClose — so `[basket]`
350	    // itself never changes) and asserts the call count stays at exactly one: a bare render-body
351	    // call fires on every render regardless of dependencies and would show 2 here, where a real
352	    // `useEffect(..., [basket])` call only fires again when `basket` itself changes.
353	    test('does not re-call capBasketQuantities on a second render that leaves the basket unchanged (proves the effect dependency, not the render body, drives it)', async () => {
354	      const { rerender, queryClient } = renderContainer();
355	      await waitFor(() => expect(mockCapBasketQuantities).toHaveBeenCalledTimes(1));
356	
357	      // Same QueryClient, same basket reference — only an effect-irrelevant prop (onClose)
358	      // changes, so `[basket]` itself is unchanged across this render.
359	      rerender(
360	        <QueryClientProvider client={queryClient}>
361	          <ChakraProvider theme={theme}>
362	            <CartDrawerContainer isOpen={true} onClose={vi.fn()} />
363	          </ChakraProvider>
364	        </QueryClientProvider>,
365	      );
366	
367	      // Give any (incorrect) render-body call a chance to fire before asserting the negative.
368	      await new Promise((resolve) => setTimeout(resolve, 0));
369	      expect(mockCapBasketQuantities).toHaveBeenCalledTimes(1);
370	    });
371	
372	    test('does not call notifyMaxQuantityReached when no correction was needed', async () => {
373	      mockCapBasketQuantities.mockResolvedValue({ status: 'not-needed' });
374	      renderContainer();
375	      await waitFor(() => expect(mockCapBasketQuantities).toHaveBeenCalledTimes(1));
376	      expect(mockNotifyMaxQuantityReached).not.toHaveBeenCalled();
377	    });
378	
379	    test('calls notifyMaxQuantityReached once the render guard reports a real correction', async () => {
380	      mockCapBasketQuantities.mockResolvedValue({ status: 'corrected' });
381	      renderContainer();
382	      await waitFor(() => expect(mockNotifyMaxQuantityReached).toHaveBeenCalledTimes(1));
383	    });
384	
385	    test('does not call notifyMaxQuantityReached when the guard reports itself skipped (mutation-in-flight)', async () => {
386	      mockCapBasketQuantities.mockResolvedValue({ status: 'skipped', reason: 'mutation-in-flight' });
387	      renderContainer();
388	      await waitFor(() => expect(mockCapBasketQuantities).toHaveBeenCalledTimes(1));
389	      expect(mockNotifyMaxQuantityReached).not.toHaveBeenCalled();
390	    });
391	  });
392	
393	  describe('secondaryActions is a real, wired ZimmCartItemActions (pass criterion 3)', () => {
394	    test('clicking Remove calls the real removeItemFromBasket mutation with this basket/item', async () => {
395	      renderContainer();
396	      fireEvent.click(screen.getByRole('button', { name: 'Remove product-a' }));
