    renderContainer();
    expect(await screen.findByTestId('mock-auth-drawer-content')).toBeInTheDocument();
  });

  test('isOpen: false (the default) renders no auth drawer content', () => {
    renderContainer();
    expect(screen.queryByTestId('mock-auth-drawer-content')).not.toBeInTheDocument();
  });
});

